 internal SessionWorkspace Workspace {get{return sessions;}}
 internal SettingsControl SettingsEditor {get{return settings;}}
 void ShowHome(){tabs.SelectedTab=library;settingsPage.Visible=false;home.Visible=true;home.BringToFront();Appearance.Apply(homeNav.Parent);}
 void RefreshReadiness(){if(!closing&&!IsDisposed)receiving.Text="Receiving support · "+support.StatusText+"     Close stops support · Minimize keeps it running";}
 void LoadDevices(){try{data=store.Load();RefreshDevices();}catch(Exception ex){data=null;devices.Items.Clear();emptyState.Text="Device vault '"+store.StorePath+"': "+ex.Message;emptyState.Visible=true;add.Enabled=false;}}
 void RefreshDevices(){if(data==null)return;string selected=Selected()==null?null:Selected().RecordId;devices.BeginUpdate();devices.Items.Clear();string query=search.Text.Trim();foreach(var record in data.Records.Where(r=>(filter.SelectedIndex!=1||r.IsFavorite)&&(filter.SelectedIndex!=2||r.LastSuccessfulConnectionUtc.HasValue)&&(r.DisplayName+" "+r.DeviceId+" "+r.Note).IndexOf(query,StringComparison.OrdinalIgnoreCase)>=0)){var item=new ListViewItem(record.DisplayName,0){Tag=record,ToolTipText=record.Note};devices.Items.Add(item);if(record.RecordId==selected)item.Selected=true;}devices.EndUpdate();emptyState.Text=data.Records.Count==0?"No saved devices. Add an authorized computer to get started.":"No devices match this search/filter.";emptyState.Visible=devices.Items.Count==0;RefreshControls();}
 DeviceRecord Selected(){return devices.SelectedItems.Count==0?null:devices.SelectedItems[0].Tag as DeviceRecord;}
 void RefreshControls(){if(closing||IsDisposed)return;var target=Selected();actions.Enabled=target!=null&&!sessions.IsDeviceBusy(target.DeviceId)&&data!=null;add.Enabled=data!=null;connect.Enabled=true;try{connect.Enabled=!sessions.IsDeviceBusy(DeviceRecord.NormalizeDeviceId(quickId.Text));}catch(ArgumentException){}GuiHelp.Set(connect,connect.Enabled?"Confirm the exact endpoint, then check this authorized remote Device ID.":"This Device ID already has a command/check running; wait or cancel it.");cancelCheck.Enabled=cancelCheck.Visible=sessions.HasPendingChecks;quickOptions.Text=(selectedContext??quickProfile)==null?"Default relay · Quick options":Mode(selectedContext??quickProfile)+" · Quick options";GuiHelp.Set(actions,actions.Enabled?"Connect, edit, favorite, or remove this local profile.":"Select a profile; wait for this Device ID's command/check to finish before editing.");}
 static string Mode(DeviceRecord record){return record.Transport==DeviceTransport.Lan?"LAN":record.UseDefaultRelay?"Default relay":"Custom relay";}
 void DrawDevice(DrawListViewItemEventArgs e){var record=(DeviceRecord)e.Item.Tag;var area=Rectangle.Inflate(e.Bounds,-6,-6);using(var fill=new SolidBrush(e.Item.Selected?Appearance.Selection:Appearance.Surface))e.Graphics.FillRectangle(fill,area);using(var pen=new Pen(e.Item.Selected?Appearance.Accent:Appearance.Border,e.Item.Selected?2:1))e.Graphics.DrawRectangle(pen,area);var line=new Rectangle(area.Left+16,area.Top+12,area.Width-32,25);using(var title=new Font(Font,FontStyle.Bold))TextRenderer.DrawText(e.Graphics,(record.IsFavorite?"★ ":"")+record.DisplayName,title,line,Appearance.Ink,TextFormatFlags.EndEllipsis);line.Y+=26;TextRenderer.DrawText(e.Graphics,record.DeviceId+" · "+Mode(record),Font,line,Appearance.Muted,TextFormatFlags.EndEllipsis);line.Y+=23;TextRenderer.DrawText(e.Graphics,record.LastSuccessfulConnectionUtc.HasValue?"Last check: "+record.LastSuccessfulConnectionUtc.Value.ToLocalTime().ToString("g"):"No successful check yet",Font,line,Appearance.Muted,TextFormatFlags.EndEllipsis);line.Y+=25;TextRenderer.DrawText(e.Graphics,"Actions ▾",Font,line,Appearance.Accent,TextFormatFlags.EndEllipsis);if(e.Item.Focused)ControlPaint.DrawFocusRectangle(e.Graphics,Rectangle.Inflate(area,-3,-3));}
 void ShowActions(){RefreshControls();if(actions.Enabled){foreach(ToolStripItem item in menu.Items)item.Enabled=true;menu.Show(actions,new Point(0,actions.Height));}}
 void Edit(DeviceRecord original){if(data==null||original!=null&&sessions.IsDeviceBusy(original.DeviceId))return;using(var editor=new DeviceEditorForm(original,false,loadRelay)){if(editor.ShowDialog(this)!=DialogResult.OK)return;try{data.Upsert(editor.Record);store.Save(data);RefreshDevices();}catch(Exception ex){connectionStatus.Text=ex.Message;LoadDevices();}}}
 void Favorite(){var target=Selected();if(target==null||sessions.IsDeviceBusy(target.DeviceId))return;try{target.IsFavorite=!target.IsFavorite;data.Upsert(target);store.Save(data);RefreshDevices();}catch(Exception ex){connectionStatus.Text=ex.Message;LoadDevices();}}
 void Remove(){var target=Selected();if(target==null||sessions.IsDeviceBusy(target.DeviceId)||!confirm("Remove local profile '"+target.DisplayName+"'? This does not revoke remote access."))return;try{data.Remove(target.RecordId);store.Save(data);if(selectedContext!=null&&selectedContext.RecordId==target.RecordId){selectedContext=null;quickProfile=null;fillingId=true;quickId.Clear();fillingId=false;}RefreshDevices();}catch(Exception ex){connectionStatus.Text=ex.Message;LoadDevices();}}
 void OpenQuickOptions(){var original=(selectedContext??quickProfile);if(original==null)original=new DeviceRecord{DisplayName="Quick connection",DeviceId=quickId.Text,UseDefaultRelay=true};using(var editor=new DeviceEditorForm(original,true,loadRelay)){if(editor.ShowDialog(this)!=DialogResult.OK)return;quickProfile=editor.Record;selectedContext=null;fillingId=true;quickId.Text=quickProfile.DeviceId;fillingId=false;devices.SelectedIndices.Clear();RefreshControls();}}
 async Task ConnectQuick(){try{var target=(selectedContext??quickProfile);if(target==null)target=new DeviceRecord{DisplayName="Quick connection",DeviceId=DeviceRecord.NormalizeDeviceId(quickId.Text),UseDefaultRelay=true};await Connect(target);}catch(Exception ex){connectionStatus.Text=ex.Message;}}
 async Task Connect(DeviceRecord target){if(closing)return;connectionStatus.Text="Checking target identity… A tab opens only after a successful check.";try{var session=await sessions.ConnectAsync(target,()=>{if(target.SavePermanentPassword&&!string.IsNullOrEmpty(target.PermanentPassword))return target.PermanentPassword;using(var prompt=new PasswordForm())return prompt.ShowDialog(this)==DialogResult.OK?prompt.Password:null;});if(closing||IsDisposed)return;if(session==null){connectionStatus.Text="Connection cancelled.";return;}bool newTab=!sessionPages.ContainsKey(session);if(newTab){var page=new TabPage(session.Target.DisplayName+" · "+session.NavigationState){ToolTipText=session.Target.DeviceId+" · "+session.NavigationState,AccessibleName=session.Target.DisplayName+" · "+session.Target.DeviceId+" · "+session.NavigationState};page.Controls.Add(new SessionPanel(session,sessions,()=>CloseSession(session),()=>{tabs.SelectedTab=library;homeNav.PerformClick();}));sessionPages.Add(session,page);tabs.TabPages.Add(page);}homeNav.Checked=true;tabs.SelectedTab=sessionPages[session];connectionStatus.Text=newTab?"Last target check succeeded. Each command opens a separate connection.":"Focused an existing tab. Its target/check history is unchanged.";var record=data==null?null:data.Find(target.RecordId);if(newTab&&record!=null){try{record.LastSuccessfulConnectionUtc=DateTime.UtcNow;data.Upsert(record);store.Save(data);RefreshDevices();}catch(Exception ex){connectionStatus.Text="Target check succeeded. Local profile timestamp could not be saved: "+ex.Message;}}}catch(Exception ex){if(!closing&&!IsDisposed)connectionStatus.Text="Target check failed: "+ex.Message;}finally{RefreshControls();}}
 async Task Execute(string command){var panel=tabs.SelectedTab==null?null:tabs.SelectedTab.Controls.OfType<SessionPanel>().FirstOrDefault();if(panel==null)return;panel.command.Text=command;await panel.Run();}
 void RefreshSessions(){if(closing||IsDisposed)return;RefreshControls();int running=sessions.Sessions.Count(s=>s.IsBusy),failed=sessions.Sessions.Count(s=>s.LastAttemptFailed);more.Text=running>0?"More · "+running+" running":failed>0?"More · "+failed+" failed":"More sessions";more.AccessibleName="More sessions · "+running+" running · "+failed+" failed";GuiHelp.Set(more,"Open session selection with each device\u0027s current operation state. "+running+" running; "+failed+" failed. These are not online-presence claims.");foreach(var entry in sessionPages){var session=entry.Key;var page=entry.Value;page.Text=session.Target.DisplayName+" · "+session.NavigationState;page.ToolTipText=page.AccessibleName=session.Target.DisplayName+" · "+session.Target.DeviceId+" · "+session.NavigationState;foreach(var panel in page.Controls.OfType<SessionPanel>())panel.RefreshState();}}
 internal ContextMenuStrip CreateSessionMenu(){var overflow=new ContextMenuStrip{AccessibleName="Device sessions with current operation states"};foreach(var entry in sessionPages){var page=entry.Value;var session=entry.Key;var item=new ToolStripMenuItem(page.Text){Checked=homeNav.Checked&&tabs.SelectedTab==page,AccessibleName=session.Target.DisplayName+" · "+session.Target.DeviceId+" · "+session.NavigationState,AccessibleDescription="Select this checked target workspace; "+session.NavigationState+" is the current operation state, not online presence."};item.Click+=(s,e)=>{homeNav.Checked=true;tabs.SelectedTab=page;};overflow.Items.Add(item);}if(overflow.Items.Count==0)overflow.Items.Add("No checked sessions").Enabled=false;return overflow;}
 void CloseSession(RemoteSession session){if(session.IsBusy){bool approved;if(injectedConfirmation)approved=confirm("Cancel/disconnect and close this tab? The remote process may keep running and the result may be unknown.");else using(var warning=new ActiveSessionCloseForm(session.Target.DisplayName))approved=warning.ShowDialog(this)==DialogResult.OK;if(!approved)return;}sessions.Close(session,true);TabPage page;if(sessionPages.TryGetValue(session,out page)){sessionPages.Remove(session);tabs.TabPages.Remove(page);page.Dispose();}if(tabs.SelectedTab==null)tabs.SelectedTab=library;}
 protected override bool ProcessCmdKey(ref Message msg,Keys keyData){if(keyData==(Keys.Control|Keys.Tab)||keyData==(Keys.Control|Keys.Shift|Keys.Tab)){int current=settingsNav.Checked?1:tabs.SelectedIndex==0?0:tabs.SelectedIndex+1;int count=tabs.TabPages.Count+1;int next=(current+(keyData==(Keys.Control|Keys.Tab)?1:-1)+count)%count;if(next==0)homeNav.PerformClick();else if(next==1)settingsNav.PerformClick();else{homeNav.Checked=true;tabs.SelectedIndex=next-1;}return true;}if(keyData==(Keys.Control|Keys.W)&&homeNav.Checked&&tabs.SelectedTab!=library&&tabs.SelectedTab!=null){var panel=tabs.SelectedTab.Controls.OfType<SessionPanel>().FirstOrDefault();if(panel!=null)CloseSession(panel.Session);return true;}return base.ProcessCmdKey(ref msg,keyData);}
 protected override void Dispose(bool disposing){if(disposing&&!IsDisposed){closing=true;sessions.Dispose();support.RequestClose();cardImages.Dispose();cardImage.Dispose();menu.Dispose();tray.Dispose();trayIcon.Dispose();}base.Dispose(disposing);}
}

