 internal ActiveSessionCloseForm(string name){Text="Close active session?";Size=new Size(540,310);MinimumSize=Size;Font=new Font("Segoe UI",10);AutoScaleMode=AutoScaleMode.Dpi;StartPosition=FormStartPosition.CenterParent;var body=new Panel{Dock=DockStyle.Fill,Padding=new Padding(24)};body.Controls.Add(WorkspaceUi.Card("Command is still running",WorkspaceUi.Text("Closing '"+name+"' cancels/disconnects this local request. The remote process may keep running; its final result may be unknown. There is no automatic retry.",true)));Controls.Add(body);var footer=new FlowLayoutPanel{Dock=DockStyle.Bottom,AutoSize=true,Padding=new Padding(20)};var keep=WorkspaceUi.Button("Keep open",()=>{DialogResult=DialogResult.Cancel;Close();},true);footer.Controls.Add(keep);footer.Controls.Add(WorkspaceUi.Button("Disconnect and close",()=>{DialogResult=DialogResult.OK;Close();}));Controls.Add(footer);AcceptButton=keep;CancelButton=keep;WorkspaceUi.Help(this);Appearance.Attach(this);Shown+=(s,e)=>keep.Focus();}
